const v52Sha=b=>createHash('sha256').update(b).digest('hex');
const v52Tuple=p=>({path:p.path,bytes:p.bytes,sha256:p.sha256});
function v52SaveHexBytes(hex){assert.ok(typeof hex==='string'&&hex.length>0&&hex.length<=512*1024&&hex.length%2===0&&/^[0-9a-f]+$/i.test(hex),'Bounded even hexadecimal SAV payload');return Buffer.from(hex,'hex');}
function v52AssertPairBytes(a,b,label){for(const k of['sav0','sav1'])assert.ok(v52SaveHexBytes(a?.[k]).equals(v52SaveHexBytes(b?.[k])),label+' SAV bytes must match; hex letter case is not byte identity');}
function v52Path(p){assert.ok(typeof p==='string'&&p.length>0&&!p.startsWith('/')&&!p.includes('\\')&&!p.split('/').some(x=>!x||x==='.'||x==='..')&&!/^[a-z]:/i.test(p),'Bounded relative archive path');return p;}
function v52Pin(p){v52Path(p.path);assert.ok(Number.isSafeInteger(p.bytes)&&p.bytes>=0&&/^[0-9a-f]{64}$/.test(p.sha256));return v52Tuple(p);}
function v52Get(files,p,cap=32*1024*1024){v52Path(p);const b=files.get(p);assert.ok(Buffer.isBuffer(b),'Required original archive bytes: '+p);assert.ok(b.length<=cap,'One bounded archive input');return b;}
