function v52Map(t){const s=t.state,z=s.snapshot;return !s.menu.active&&!s.qty.active&&!s.record.active&&!z.fight.active&&!z.spe.active&&!z.result.active&&!z.top.active&&!z.report.active&&s.march.pick===1&&s.march.battlePick===0&&[0,7].includes(s.march.phase)&&s.overworld==='map';}
function v52PairInspection(a,b,anchor){const x=structuredClone(a),y=structuredClone(b);delete x.state.overworld;delete y.state.overworld;assert.deepEqual(y,x,'A/B full native fields except source-defined cached display must agree');if(anchor)assert.deepEqual(x,anchor,'No uncommanded change can be hidden by stabilization');const s=b.state,z=s.snapshot,expected=z.fight.active||z.spe.active||z.result.active||z.top.active||z.report.active||s.qty.active||s.record.active?'other':s.menu.active?(s.menu.context===1?'classic-menu':'other'):'map',ready=a.state.overworld===b.state.overworld&&(b.meta.overworldMode!=='hd-map'||b.state.overworld===expected);if(ready)assert.deepEqual(a,b,'The accepted A/B tickets are independently read and complete');return{anchor:x,ready,expected};}

