 return{acceptedForSupplementalReadOnlyClosure:true,originalLifecycleClosed:false,originalFlagsRewritten:false,auditPin:{path,bytes:b.length,sha256:v52Sha(b)},samples:p.samples,sampler:p.sampler,originalTargets:p.originalTargets,newOsCheckByReader:false};
